def queens_attacking_king(queens,king):
    occupied={tuple(queen) for queen in queens};answer=[]
    for dr in (-1,0,1):
        for dc in (-1,0,1):
            if dr==dc==0:continue
            row,column=king
            while 0<=row+dr<8 and 0<=column+dc<8:
                row+=dr;column+=dc
                if (row,column) in occupied:answer.append([row,column]);break
    return answer

